// The answer pages (site/answer-*.html, generated by scripts/site-answers.mjs from data/answers.json) against the data and against the Explorer.
//  1. every row of every table is recomputed here from the raw records with a short implementation of its own: the same verdict, the same offset to two decimals, the same value at the reference x;
//     and the counts in each paragraph are the counts of the table rows
//  2. in a browser, every offset and verdict on a page is the one the Explorer's Tension view shows for the same simulation, relation and epoch (the epochs the Tension view offers)
//  3. the pages state what they should (the limits, that no outside expert has reviewed them, who the anchor is), say nothing a page of this project may not say, and their titles match their epochs
// Needs dist/ (scripts/verify-all.sh or the build scripts).
import assert from "node:assert/strict";
import http from "node:http";
import vm from "node:vm";
import path from "node:path";
import { readFile, readdir } from "node:fs/promises";
import { launchBrowser } from "./browser-options.mjs";
import { doiWording } from "./release-doi.mjs";

const ROOT = new URL("../", import.meta.url), DIST = new URL("dist/", ROOT).pathname;
const spec = JSON.parse(await readFile(new URL("data/answers.json", ROOT), "utf8"));
const release = JSON.parse(await readFile(new URL("data/release.json", ROOT), "utf8")), SITE = "https://shubhanbhatia42.github.io/sim-highline";
const embeds = [];   // the iframe addresses the pages offer, loaded in the browser below
const load = async f => { const c = { globalThis: {} }; vm.runInNewContext(await readFile(new URL(f, ROOT), "utf8"), c); return c.globalThis; };
const C = (await load("compare.js")).SimHighlineCompare, L = (await load("highline/logic.js")).SimHighlineLogic;
let recs = []; for (const f of (await readdir(new URL("data/curves/", ROOT))).filter(f => f.endsWith(".json"))) recs.push(...JSON.parse(await readFile(new URL(`data/curves/${f}`, ROOT), "utf8")).records);
// the Explorer's own relation for a record (highline/index.html: relKey)
const relOf = r => r.relation !== "mzr" ? r.relation : r.definitions?.metallicityQuantity === "gas-O/H" ? "mzr" : /Zsun/.test(r.axes?.yDefinition || "") ? "mzrz" : "mzrraw";
recs = recs.filter(r => r.representation).map(r => ({ ...r, relation: relOf(r) }));
const sims = recs.filter(r => r.kind !== "observation"), obs = recs.filter(r => r.kind === "observation");
const decode = s => s.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
const text = h => decode(h.replace(/<br>/g, " ‖ ").replace(/<[^>]+>/g, ""));
const num = t => { const m = /(\d+\.\d+)/.exec(t); if (!m) return null; return /^\s*[−-]\s*\d/.test(t) ? -+m[1] : +m[1]; };

// ---- 1. the tables, recomputed
const pts = (r, z) => {
  const rep = r.representation;
  if (rep.type === "points") return rep.points.filter(p => Number.isFinite(p.x) && Number.isFinite(p.y)).map(p => ({ x: p.x, y: p.y })).sort((a, b) => a.x - b.x);
  const f = C.evaluator(r); if (!f) return []; const o = [];
  for (let i = 0; i <= 40; i++) { const x = r.domain.xMin + (r.domain.xMax - r.domain.xMin) * i / 40, y = f(x, z); if (Number.isFinite(y)) o.push({ x, y }); } return o;
};
const rows = []; // everything the pages claim, for the browser check
for (const a of spec.answers) {
  const html = await readFile(path.join(DIST, "site", a.page), "utf8");
  const main = html.slice(html.indexOf("<main"), html.indexOf("</main>"));
  assert(!/\{\{|undefined|NaN|\[object/.test(main), `${a.page}: unreplaced placeholder or broken value`);
  const prim = L.primaryUnits(sims.filter(r => r.relation === a.relation));
  for (let i = 0; i < a.epochs.length; i++) {
    const z = a.epochs[i], tab = new RegExp(`<table class="stack" id="t${i}">([\\s\\S]*?)</table>`).exec(main);
    assert(tab, `${a.page}: table for z = ${z}`);
    const rx = new RegExp(a.anchors ? a.anchors[String(z)] : a.anchor);
    const O = obs.filter(r => r.relation === a.relation && ((z >= r.epoch.zMin - .1 && z <= r.epoch.zMax + .1) || Math.abs(r.epoch.zRepresentative - z) <= L.tol(z)));
    const anchor = O.filter(r => rx.test(r.source)).sort((p, q) => Math.abs(p.epoch.zRepresentative - z) - Math.abs(q.epoch.zRepresentative - z))[0];
    assert(anchor, `${a.page}: an anchor at z = ${z}`);
    assert(main.includes(`The anchor observation is ${anchor.source.replace(/&/g, "&amp;")}`) || main.includes(`The anchor observation is ${anchor.source}`), `${a.page}: the paragraph for z = ${z} names the anchor ${anchor.source}`);
    // the simulations that must be in the table: one fiducial run per simulation within the epoch's window
    const best = new Map();
    for (const r of sims) { if (r.relation !== a.relation) continue; const d = Math.abs(r.epoch.zRepresentative - z); if (d > L.tol(z)) continue; const k = L.unitOf(r); if (!best.has(k) || d < best.get(k).d) best.set(k, { r, d }); }
    const want = [...best.values()].map(v => v.r).filter(r => prim.has(L.unitOf(r)));
    const trs = [...tab[1].matchAll(/<tr><th scope="row">([\s\S]*?)<\/th>([\s\S]*?)<\/tr>/g)];
    assert.equal(trs.length, want.length, `${a.page} z = ${z}: one row per simulation (${want.length} expected, ${trs.length} found)`);
    const A = pts(anchor, z); let k = 0, no = 0, none = 0;
    for (const t of trs) {
      const head = text(t[1]), cells = [...t[2].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map(m => text(m[1]));
      const rec = want.find(r => head.includes(r.source) && head.includes(String(r.run || "").slice(0, 40).replace(/…$/, "")));
      assert(rec, `${a.page} z = ${z}: a record for the row "${head.slice(0, 60)}"`);
      const P = pts(rec, z), v = C.compatible(anchor, rec).verdict, scatter = rec.representation.type === "points" && rec.representation.connect === false;
      const off = scatter ? null : L.medianOffset(A, P, C.interpolate), word = v === "comparable" ? "comparable" : v === "not-comparable" ? "not comparable" : "comparable with caveats";
      assert(cells[1].replace(/^[✓~✕]\s*/, "").startsWith(word) && (word !== "comparable" || !/with caveats|not comparable/.test(cells[1])), `${a.page} z = ${z} ${rec.source}: verdict "${cells[1].slice(0, 40)}", expected ${word}`);
      if (off == null) assert(!/^[+−-]\d/.test(cells[2]), `${a.page} z = ${z} ${rec.source}: no offset expected, found "${cells[2]}"`);
      else assert(Math.abs(num(cells[2]) - +off.toFixed(2)) < 1e-9, `${a.page} z = ${z} ${rec.source}: offset ${cells[2]} against ${off.toFixed(2)}`);
      const x = P.length && a.refX >= P[0].x && a.refX <= P[P.length - 1].x ? C.interpolate(P, a.refX) : null;
      if (x == null) assert(/outside range/.test(cells[3]), `${a.page} z = ${z} ${rec.source}: value at the reference x should be outside the range`); else assert(Math.abs(num(cells[3]) - +x.toFixed(2)) < 1e-9, `${a.page} z = ${z} ${rec.source}: value at the reference x ${cells[3]} against ${x.toFixed(2)}`);
      if (v === "not-comparable") no++; else if (off == null) none++; else k++;
      rows.push({ page: a.page, rel: a.relation, z, source: rec.source, offset: off, verdict: v });
    }
    // the paragraph's counts are the table's counts
    const para = text(new RegExp(`<h2 id="e${i}-h">[\\s\\S]*?</h2>\\s*<p>([\\s\\S]*?)</p>`).exec(main)[1]);
    assert(para.includes(`At z ≈ ${z}, ${trs.length} simulations`), `${a.page} z = ${z}: the paragraph counts ${trs.length} simulations: ${para.slice(0, 90)}`);
    if (k >= 3) assert(para.includes(`${k} of them can be compared with it`), `${a.page} z = ${z}: "${k} of them can be compared" in: ${para.slice(0, 260)}`);
    else if (k > 0) assert(para.includes(`Only ${k} can be compared with it`), `${a.page} z = ${z}: "Only ${k} can be compared"`);
    if (no === trs.length) assert(para.includes(`None of the ${trs.length} can be compared`), `${a.page} z = ${z}: none can be compared`); else if (no) assert(new RegExp(`\\b${no} (cannot|cannot be compared)`).test(para), `${a.page} z = ${z}: "${no} cannot be compared" in: ${para.slice(0, 400)}`);
    if (none) assert(new RegExp(`\\b${none} (has|have) no curve that overlaps`).test(para), `${a.page} z = ${z}: ${none} with no overlap`);
    assert.equal(k + no + none, trs.length, `${a.page} z = ${z}: every row is compared, not comparable or without overlap`);
  }
  // ---- 3. what a page must say and must not say
  const lo = Math.min(...a.epochs), hi = Math.max(...a.epochs);
  assert(a.short.includes(`z = ${lo} to ${hi}`), `${a.id}: the short title names the epochs (z = ${lo} to ${hi}): "${a.short}"`);
  assert(a.question.includes("z = ") ? a.question.includes(`z = ${lo} to ${hi}`) : true, `${a.id}: the question names the epochs`);
  assert((html.match(/<h1>/g) || []).length === 1 && html.includes(`<h1>${a.question.replace(/&/g, "&amp;")}</h1>`), `${a.page}: one h1, the question`);
  assert(/No outside expert has reviewed this page/.test(main), `${a.page}: says no outside expert has reviewed it`);
  // the citation: the dataset's own wording (with the DOI caveat) and this page's address
  const cite = /<blockquote class="cite"><p>([\s\S]*?)<\/p><\/blockquote>/.exec(main);
  assert(cite, `${a.page}: a citation block`);
  const want = doiWording(release).cite("Bhatia, S.", release.released.slice(0, 4), release.title), got = text(cite[1]);
  assert(got.includes(want), `${a.page}: the citation carries the dataset's citation wording:\n  ${want}\nnot found in\n  ${got}`);
  assert(got.includes(`${SITE}/site/${a.page}`) && got.includes(a.question), `${a.page}: the citation names this page and its question`);
  // the embed snippet: an iframe on the Explorer at this relation and the middle epoch, with a title and lazy loading
  const code = /<pre><code>([\s\S]*?)<\/code><\/pre>/.exec(main); assert(code, `${a.page}: an embed snippet`);
  const m = /^<iframe src="([^"]+)" width="(\d+)" height="(\d+)" title="([^"]+)" loading="lazy"><\/iframe>$/.exec(decode(code[1]).trim());
  assert(m, `${a.page}: the snippet is one iframe with a title: ${decode(code[1]).slice(0, 120)}`);
  const mid = a.epochs[a.epochs.length > 1 ? 1 : 0];
  assert.equal(m[1], `${SITE}/highline.html#embed=1&r=${a.relation}&z=${mid}`, `${a.page}: the iframe address`);
  assert(+m[2] >= 600 && +m[3] >= 400, `${a.page}: the iframe is a usable size`);
  embeds.push({ page: a.page, url: m[1].replace(SITE, "") });
  assert(/It does not rank simulations/.test(main) && /not a verdict/i.test(main), `${a.page}: says it is not a ranking and that offsets of curves that cannot be compared are not verdicts`);
  for (const t of a.limits) assert(main.includes(t.replace(/&/g, "&amp;")), `${a.page}: the limit "${t.slice(0, 50)}…" is on the page`);
  assert((main.match(/class="btn main"/g) || []).length === 1 && new RegExp(`class="btn main" href="\\.\\./highline\\.html#r=${a.relation}&amp;z=\\d+"`).test(main), `${a.page}: one primary button into the Explorer on this relation`);
  assert(a.epochs.every((z, i) => main.includes(`href="../highline.html#r=${a.relation}&amp;z=${z}">Open z ≈ ${z} in the Explorer</a>`)), `${a.page}: each epoch links to the Explorer`);
  const plain = text(main);
  assert(!/\b(novel|first[- ]ever|unprecedented|ground-?breaking|new method|new approach|state[- ]of[- ]the[- ]art)\b/i.test(plain), `${a.page}: novelty wording`);
  assert(!/\bAI\b|language model|\bGPT\b|chatbot/i.test(plain), `${a.page}: no mention of AI`);
  assert(!/\bS[1-9][a-z]?\b/.test(plain), `${a.page}: no study-code names`);
}
// the index lists every answer, and the front page links to it
const idx = await readFile(path.join(DIST, "site", "answers.html"), "utf8"), front = await readFile(path.join(DIST, "site", "index.html"), "utf8");
for (const a of spec.answers) assert(idx.includes(`href="${a.page}"`), `answers.html lists ${a.page}`);
assert(front.includes('href="answers.html">Read an answer'), "the front page links to the answers");
console.log(`answer pages: ${spec.answers.length} pages, ${rows.length} table rows recomputed from the records (verdict, offset and value at the reference x), the paragraph counts are the table counts`);

// ---- 2. against the Explorer's Tension view
const TYPES = { ".html": "text/html", ".js": "text/javascript", ".json": "application/json", ".css": "text/css", ".csv": "text/csv" };
const server = http.createServer(async (req, res) => { const p = decodeURIComponent(new URL(req.url, "http://x").pathname); try { const f = path.join(DIST, p.endsWith("/") ? p + "index.html" : p); const b = await readFile(f); res.writeHead(200, { "content-type": TYPES[path.extname(f)] || "application/octet-stream" }); res.end(b); } catch (e) { res.writeHead(404); res.end(); } });
await new Promise(r => server.listen(0, "127.0.0.1", r));
const BASE = `http://127.0.0.1:${server.address().port}`, browser = await launchBrowser();
let compared = 0;
try {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const TZ = new Set([0, 1, 2, 4, 6, 8]);
  for (const z of [...new Set(rows.filter(r => TZ.has(r.z)).map(r => r.z))]) {
    const p = await ctx.newPage();
    await p.goto(`${BASE}/highline.html#r=gsmf&z=0&m=tension&tz=${z}`, { waitUntil: "load" });
    await p.waitForSelector("#tension td[data-r]", { timeout: 30000 });
    const cells = await p.evaluate(() => [...document.querySelectorAll("#tension td[data-r][data-s]")].map(td => ({ rel: td.dataset.r, src: td.dataset.s, title: td.getAttribute("title") })));
    await p.close();
    for (const r of rows.filter(r => r.z === z && r.offset != null)) {
      const hit = cells.find(c => c.rel === r.rel && c.src === r.source); if (!hit) continue;   // the Tension view has no column for the UV luminosity function
      const m = /: (above|below) by (\d+\.\d+) in y units \(([a-z -]+?)(?::|\))/.exec(hit.title);
      assert(m, `Explorer tension title not understood: ${hit.title.slice(0, 120)}`);
      const d = (m[1] === "above" ? 1 : -1) * +m[2], verdict = m[3].replace(/ /g, "-");
      assert(Math.abs(d - +r.offset.toFixed(2)) < 1e-9, `${r.page} z = ${z} ${r.source}: the page says ${r.offset.toFixed(2)}, the Explorer's Tension view says ${d}`);
      assert.equal(verdict, r.verdict, `${r.page} z = ${z} ${r.source}: verdict on the page ${r.verdict}, in the Explorer ${verdict}`);
      compared++;
    }
  }
  assert(compared >= 15, `at least 15 page rows were matched with Tension cells, got ${compared}`);
  // the snippets on the pages open the Explorer on the right relation, draw curves and hide the chrome
  for (const e of embeds) {
    const p = await ctx.newPage(), errors = []; p.on("pageerror", x => errors.push(String(x)));
    await p.goto(BASE + e.url, { waitUntil: "load" });
    await p.waitForFunction(() => !document.getElementById("boot") && document.querySelectorAll("#stage path.curve").length >= 3, null, { timeout: 30000 });
    const r = await p.evaluate(() => ({ rail: getComputedStyle(document.getElementById("presets")).display, title: document.getElementById("shTitle").textContent }));
    assert.equal(r.rail, "none", `${e.page}: embed mode hides the relation list`);
    assert.deepEqual(errors, [], `${e.page}: no page errors in the embed`);
    await p.close();
  }
} finally { await browser.close(); server.close(); }
console.log(`answer pages and the Explorer: ${compared} offsets and verdicts are the same in the Explorer's Tension view`);
